def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        angle_match = re.search(r"<([^<>]*)>", value)
        if angle_match:
            value = angle_match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return value

    def normalize_phone(value):
        value = value or ""
        value = re.split(r"(?i:ext|x|#)", value, maxsplit=1)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = (value or "").strip()

        zip_plus_four = re.fullmatch(r"(\d{5})-\d{4}", value)
        if zip_plus_four:
            value = zip_plus_four.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value or "")
            if tag.strip()
        }

    def is_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    # Normalize rows and discard those lacking both a valid email and phone.
    records = []
    for input_index, row in enumerate(rows):
        record = {
            "index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated": parse_updated(row["updated"]),
            "source": row["source"].strip().lower(),
        }

        if record["email"] or record["phone"]:
            records.append(record)

    # Disjoint-set union for transitive matching.
    parent = list(range(len(records)))
    rank = [0] * len(records)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a

        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for i, record in enumerate(records):
        email = record["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone = record["phone"]
        last_name = record["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in phone_last_name_owner:
                union(i, phone_last_name_owner[key])
            else:
                phone_last_name_owner[key] = i

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(find(i), []).append(record)

    def choose(group, field):
        candidates = [record for record in group if record[field]]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda record: (
                record["source"] == "manual",
                record["updated"],
                -record["index"],
            ),
        )
        return chosen[field]

    output = []
    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(record["index"] for record in group),
    )

    for group in ordered_groups:
        tags = set()
        for record in group:
            tags.update(record["tags"])

        latest_updated = max(record["updated"] for record in group)

        output.append(
            {
                "first_name": choose(group, "first_name"),
                "last_name": choose(group, "last_name"),
                "zip": choose(group, "zip"),
                "email": choose(group, "email"),
                "phone": choose(group, "phone"),
                "source": choose(group, "source"),
                "tags": ";".join(sorted(tags)),
                "opted_out": (
                    "Y" if any(record["opted_out"] for record in group) else "N"
                ),
                "updated": latest_updated.strftime("%Y-%m-%d"),
            }
        )

    return output
